import{_ as d,o as t,a as o,b as c}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"附录","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/appendix"},{"text":"命名转换规则对照表","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/naming_conversion_table"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/naming_conversion_table.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/naming_conversion_table.md","outlineHeaders":[{"level":2,"title":"转换规则概述","slug":"转换规则概述","link":"#转换规则概述"},{"level":2,"title":"对照表","slug":"对照表","link":"#对照表"},{"level":2,"title":"特殊情况说明","slug":"特殊情况说明","link":"#特殊情况说明"},{"level":3,"title":"连续大写字母","slug":"连续大写字母","link":"#连续大写字母"},{"level":3,"title":"数字与字母相邻","slug":"数字与字母相邻","link":"#数字与字母相邻"},{"level":3,"title":"首字母大写","slug":"首字母大写","link":"#首字母大写"},{"level":2,"title":"工程中的实际影响","slug":"工程中的实际影响","link":"#工程中的实际影响"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),a={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/naming_conversion_table.md"};function r(n,e,l,i,s,m){return t(),o("div",null,[...e[0]||(e[0]=[c(`<div><article class="markdown-body"><h1>命名转换规则对照表</h1><p>本文属于基础内容，介绍自定义算子工程中的命名转换规则。算子类型（OpType）通常采用大驼峰命名方式，配置中的实现文件名和核函数（Kernel）入口名通常采用小写下划线命名方式。默认情况下，框架会根据OpType生成这些名称。</p><h2 id="转换规则概述">转换规则概述<a class="header-anchor" href="#转换规则概述">​</a></h2><p>转换发生在构建阶段。构建工具会根据已注册的OpType生成配置和相关代码；算子运行时使用已经生成的配置和符号，不会再次转换名称。</p><p>构建工具从左向右按以下规则处理字符：</p><ol><li><strong>首字符大写转小写</strong>：首字符直接转换为小写，不插入下划线。</li><li><strong>前一个字符不是大写字母时插入下划线</strong>：当前字符是大写字母，且前一个字符是小写字母或数字时，在当前字符前插入下划线，并将当前字符转换为小写。</li><li><strong>连续大写与后续单词之间插入下划线</strong>：当前字符和前一个字符都是大写字母，但下一个字符是小写字母时，在当前字符前插入下划线，并将当前字符转换为小写。</li><li><strong>其他字符直接转换或保留</strong>：其他大写字母直接转换为小写；小写字母和数字保持不变。</li></ol><p>构建工具还会检查OpType是否符合推荐的命名规范：首字符为大写字母，后续字符只能是字母或数字。不符合规范时会输出告警，建议使用大驼峰命名。</p><h2 id="对照表">对照表<a class="header-anchor" href="#对照表">​</a></h2><p>下表列出了常见算子名称的转换结果。结果以当前构建工具的实际转换结果为准。</p><table><thead><tr><th>算子类型（大驼峰）</th><th>文件名/核函数（Kernel）入口名（小写下划线）</th><th>转换说明</th></tr></thead><tbody><tr><td><code>AddCustom</code></td><td><code>add_custom</code></td><td>首字符转小写，<code>Custom</code>前插入下划线</td></tr><tr><td><code>ReduceMaxCustom</code></td><td><code>reduce_max_custom</code></td><td><code>Max</code>和<code>Custom</code>前分别插入下划线</td></tr><tr><td><code>MatmulCustom</code></td><td><code>matmul_custom</code></td><td><code>Custom</code>前插入下划线</td></tr><tr><td><code>BatchNormCustom</code></td><td><code>batch_norm_custom</code></td><td><code>Norm</code>和<code>Custom</code>前分别插入下划线</td></tr><tr><td><code>Conv2DCustom</code></td><td><code>conv2_d_custom</code></td><td><code>D</code>前是数字<code>2</code>，因此在<code>D</code>前插入下划线</td></tr><tr><td><code>SoftmaxCustom</code></td><td><code>softmax_custom</code></td><td><code>Custom</code>前插入下划线</td></tr><tr><td><code>ReluCustom</code></td><td><code>relu_custom</code></td><td><code>Custom</code>前插入下划线</td></tr><tr><td><code>LayerNormCustom</code></td><td><code>layer_norm_custom</code></td><td><code>Norm</code>和<code>Custom</code>前分别插入下划线</td></tr><tr><td><code>SliceCustom</code></td><td><code>slice_custom</code></td><td><code>Custom</code>前插入下划线</td></tr><tr><td><code>GatherV2Custom</code></td><td><code>gather_v2_custom</code></td><td><code>V</code>前是小写字母，<code>Custom</code>前是数字<code>2</code></td></tr><tr><td><code>SplitVCustom</code></td><td><code>split_v_custom</code></td><td><code>V</code>和<code>Custom</code>前分别插入下划线</td></tr><tr><td><code>TransposeCustom</code></td><td><code>transpose_custom</code></td><td><code>Custom</code>前插入下划线</td></tr><tr><td><code>OneHotCustom</code></td><td><code>one_hot_custom</code></td><td><code>Hot</code>和<code>Custom</code>前分别插入下划线</td></tr><tr><td><code>TopKCustom</code></td><td><code>top_k_custom</code></td><td><code>K</code>和<code>Custom</code>前分别插入下划线</td></tr></tbody></table><h2 id="特殊情况说明">特殊情况说明<a class="header-anchor" href="#特殊情况说明">​</a></h2><h3 id="连续大写字母">连续大写字母<a class="header-anchor" href="#连续大写字母">​</a></h3><p>连续大写字母通常表示缩写。转换工具不会在缩写的每个字母前都插入下划线，而是在缩写和后续单词的边界插入下划线。</p><ul><li><code>AbcAAc</code>转换为<code>abc_a_ac</code>：第一个<code>A</code>前是小写字母<code>c</code>，第二个<code>A</code>后是小写字母<code>c</code>，两处都会插入下划线。</li><li><code>GRUCell</code>转换为<code>gru_cell</code>：<code>C</code>前是大写字母<code>U</code>，后是小写字母<code>e</code>，因此在<code>C</code>前插入下划线。</li><li><code>HTTPServerCustom</code>转换为<code>http_server_custom</code>：在<code>Server</code>和<code>Custom</code>的单词边界插入下划线。</li></ul><h3 id="数字与字母相邻">数字与字母相邻<a class="header-anchor" href="#数字与字母相邻">​</a></h3><p>数字本身保持不变。数字后的字符如果是大写字母，由于数字不是大写字母，会触发规则2。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>GatherV2Custom -&gt; gather_v2_custom
Conv2DCustom   -&gt; conv2_d_custom
</code></pre></div><p>因此，不能仅凭常见缩写习惯把<code>Conv2D</code>写成<code>conv2d</code>；当前实现的实际转换结果是<code>conv2_d</code>。</p><h3 id="首字母大写">首字母大写<a class="header-anchor" href="#首字母大写">​</a></h3><p>首字母直接转换为小写，不插入下划线。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>Add    -&gt; add
Reduce -&gt; reduce
</code></pre></div><h2 id="工程中的实际影响">工程中的实际影响<a class="header-anchor" href="#工程中的实际影响">​</a></h2><p>默认情况下，开发者需要保证以下对应关系：</p><table><thead><tr><th>项目</th><th>命名方式</th><th><code>AddCustom</code>示例</th></tr></thead><tbody><tr><td>算子类型、<code>OpDef</code>类名、构造函数名、<code>OP_ADD</code>参数</td><td>大驼峰</td><td><code>AddCustom</code></td></tr><tr><td>核函数（Kernel）源码文件名</td><td>建议使用小写下划线，可由CMake显式指定</td><td><code>add_custom.cpp</code></td></tr><tr><td>核函数（Kernel）入口函数名</td><td>默认使用小写下划线，需与<code>opInterface.value</code>一致</td><td><code>add_custom</code></td></tr></tbody></table><p>使用msOpGen创建算子工程时，工具通常会按上述规则生成初始文件名和核函数（Kernel）入口名。构建后可以通过生成的<code>ops-info.ini</code>和aclnn头文件确认实际转换结果，应用程序也应以这些构建产物为准。</p><p>如果修改了aclnn工程名前缀或直调接口前缀，生成文件和接口的前缀也会变化。重命名Host或核函数（Kernel）源文件后，还需要同步修改CMake中的源文件列表。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../design_and_implementation/operator_prototype_definition.html">算子原型定义</a>：了解OpType、<code>OpDef</code>类和<code>OP_ADD</code>注册方法。</li><li><a href="../design_and_implementation/kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：了解核函数（Kernel）入口格式和参数顺序。</li><li><a href="../invocation/single_operator_api_call.html">单算子API调用</a>：了解两段式aclnn接口及其参数命名规则。</li></ul></article></div>`,1)])])}const h=d(a,[["render",r]]);export{_ as __pageData,h as default};
